package com.priperi;
import android.content.Context;import org.json.*;import java.security.*;import java.security.spec.*;import java.util.*;import javax.crypto.*;import javax.crypto.spec.SecretKeySpec;
/** One-use encrypted account move. All methods run on the serialized vault worker. */
final class AccountTransfer {
 static final class Offer implements AutoCloseable {final byte[] entropy,historyKey;final String lookup,owner;final long expiresAt;final java.io.File historyFile;Offer(byte[] entropy,byte[] key,String lookup,String owner,long expiry,java.io.File file){historyFile=file;this.entropy=entropy;historyKey=key;this.lookup=lookup;this.owner=owner;expiresAt=expiry;}public void close(){Arrays.fill(entropy,(byte)0);Arrays.fill(historyKey,(byte)0);}}
 static JSONObject request(Vault v,String operation,JSONObject payload)throws Exception{return Session.request(Session.endpoint(),payload.put("operation",operation).put("deviceSecret",v.identity().getString("deviceSecret")),null,true).getJSONObject("data");}
 static String lookup(byte[] entropy)throws Exception{return TransferCipher.lookup(entropy);}
 static Offer begin(Vault v,char[] password)throws Exception {
  if(v.account()==null||v.transferIn()!=null||v.transferOut()!=null)throw new SecurityException("Finish or cancel the existing account move first.");
  Session.continueAccount(v,null,new String(password));JSONObject profile=Repository.call(v,"getAccount",new JSONObject());Crypto.verifyProfile(profile);
  byte[] entropy=TransferPhrase.fresh(),historyKey=new byte[32],claim=new byte[32];SecureRandom random=new SecureRandom();random.nextBytes(historyKey);random.nextBytes(claim);
  try{
   String lookup=lookup(entropy),claimSecret=java.util.Base64.getUrlEncoder().withoutPadding().encodeToString(claim),claimHash=TransferCipher.hash(claimSecret.getBytes(Crypto.UTF8));KeyPair authorizer=KeyDelegation.temporaryKey();String temporary=KeyDelegation.publicValue(authorizer),owner=profile.getString("uid");
   JSONArray chain=profile.optJSONArray("delegations")==null?new JSONArray():new JSONArray(profile.getJSONArray("delegations").toString());if(chain.length()>30)throw new SecurityException("This account reached its supported secure-move limit. No account data was changed.");chain.put(v.crypto().authorize(v.identity(),owner,temporary));
   JSONObject identity=new JSONObject();for(String field:new String[]{"private","hpke","signing","fingerprint"})identity.put(field,v.identity().getString(field));identity.put("historySecret",v.identity().optString("historySecret",v.identity().getString("deviceSecret")));
   JSONObject data=new JSONObject().put("version",1).put("uid",owner).put("identity",identity).put("claimSecret",claimSecret).put("authorizer",Crypto.b64(authorizer.getPrivate().getEncoded())).put("historyKey",Crypto.b64(historyKey));
   byte[] plain=data.toString().getBytes(Crypto.UTF8);String capsule;try{capsule=TransferCipher.seal(plain,entropy,password);}finally{Arrays.fill(plain,(byte)0);}
   String nonce=Repository.call(v,"transferChallenge",new JSONObject().put("lookup",lookup)).getString("nonce");
   v.transferOut(new JSONObject().put("uid",owner).put("lookup",lookup).put("passwordCheck",passwordCheck(v,password,lookup)));
   java.io.File historyFile=v.transferFile(lookup);v.exportTransfer(historyFile,historyKey,()->{});
   String signature=v.crypto().sign(String.join("\n","priperi-transfer-prepare-v1",owner,lookup,nonce,claimHash,TransferCipher.hash(capsule.getBytes(Crypto.UTF8)),temporary).getBytes(Crypto.UTF8));
   JSONObject response=Repository.call(v,"prepareTransfer",new JSONObject().put("lookup",lookup).put("nonce",nonce).put("claimHash",claimHash).put("capsule",capsule).put("chain",chain).put("signature",signature));
   return new Offer(entropy,historyKey,lookup,owner,response.getLong("expiresAt"),historyFile);
  }catch(Exception e){Arrays.fill(entropy,(byte)0);Arrays.fill(historyKey,(byte)0);throw e;}finally{Arrays.fill(claim,(byte)0);}
 }
 static void inspect(Vault v,byte[] entropy,char[] password)throws Exception {
  if(!v.emptyForTransfer())throw new SecurityException("This phone already has an account or saved history. Use an empty Priperi installation.");String lookup=lookup(entropy);JSONObject old=v.transferIn();if(old!=null&&!lookup.equals(old.optString("lookup")))throw new SecurityException("Cancel the current receive attempt first.");
  JSONObject response=request(v,"readTransfer",new JSONObject().put("lookup",lookup)),profile=response.getJSONObject("account");Crypto.verifyProfile(profile);byte[] plain=TransferCipher.open(response.getString("capsule"),entropy,password);
  JSONObject data;try{data=new JSONObject(BackupCodec.utf8(plain));}finally{Arrays.fill(plain,(byte)0);}
  if(data.getInt("version")!=1||!profile.getString("uid").equals(data.getString("uid")))throw new GeneralSecurityException("Transfer account mismatch");JSONObject identity=data.getJSONObject("identity");Crypto.verifyPrivateIdentity(identity);
  if(!profile.getString("fingerprint").equals(identity.getString("fingerprint"))||!profile.getString("hpke").equals(identity.getString("hpke"))||!profile.getString("signing").equals(identity.getString("signing")))throw new GeneralSecurityException("Transfer security key mismatch");
  JSONArray chain=new JSONArray(response.getJSONArray("chain").toString());List<String> keys=KeyDelegation.keys(data.getString("uid"),identity.getString("fingerprint"),identity.getString("signing"),Crypto.certificates(chain));
  PrivateKey authorizer=KeyFactory.getInstance("EC").generatePrivate(new PKCS8EncodedKeySpec(Crypto.unb64(data.getString("authorizer"))));String child=v.crypto().publicSigning(),parent=keys.get(keys.size()-1);
  String certificate=KeyDelegation.sign(authorizer,KeyDelegation.context(data.getString("uid"),identity.getString("fingerprint"),parent,child).getBytes(Crypto.UTF8));if(!KeyDelegation.verify(parent,KeyDelegation.context(data.getString("uid"),identity.getString("fingerprint"),parent,child).getBytes(Crypto.UTF8),certificate))throw new GeneralSecurityException("Invalid transfer authorisation");chain.put(new JSONObject().put("key",child).put("signature",certificate));
  JSONObject target=new JSONObject().put("installation",v.identity().getString("installation")).put("deviceId",v.identity().getString("deviceId")).put("signing",child).put("chain",chain);
  if(Crypto.unb64(data.getString("historyKey")).length!=32||!data.getString("claimSecret").matches("[A-Za-z0-9_-]{43}")||!identity.getString("historySecret").matches("[A-Za-z0-9_-]{43}"))throw new GeneralSecurityException("Invalid transfer secret");
  data.remove("authorizer");data.put("lookup",lookup).put("profile",profile).put("target",target).put("passwordCheck",passwordCheck(v,password,lookup));v.transferIn(data);
 }
 static String passwordCheck(Vault v,char[] password,String lookup)throws Exception{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(java.util.Base64.getUrlDecoder().decode(v.identity().getString("deviceSecret")),"HmacSHA256"));return Crypto.b64(mac.doFinal(("priperi-transfer-password-v1\n"+lookup+"\n"+new String(password)).getBytes(Crypto.UTF8)));}
 static JSONObject accept(Vault v,char[] password)throws Exception {
  JSONObject data=v.transferIn();if(data==null)throw new SecurityException("Enter the transfer words first.");String lookup=data.getString("lookup");if(!MessageDigest.isEqual(passwordCheck(v,password,lookup).getBytes(Crypto.UTF8),data.getString("passwordCheck").getBytes(Crypto.UTF8)))throw new GeneralSecurityException("The current app password does not match this transfer.");
  if(v.account()!=null&&data.getString("uid").equals(v.account().getString("uid")))return Session.continueAccount(v,null,new String(password));
  JSONObject target=data.getJSONObject("target");String claimHash=TransferCipher.hash(data.getString("claimSecret").getBytes(Crypto.UTF8)),proof=TransferCipher.hash(v.identity().getString("deviceSecret").getBytes(Crypto.UTF8));
  String context=String.join("\n","priperi-transfer-accept-v1",lookup,data.getString("uid"),claimHash,proof,target.getString("installation"),target.getString("deviceId"),target.getString("signing"),KeyDelegation.digest(Crypto.certificates(target.getJSONArray("chain"))));
  JSONObject result=request(v,"acceptTransfer",new JSONObject().put("lookup",lookup).put("claimSecret",data.getString("claimSecret")).put("target",target).put("signature",v.crypto().sign(context.getBytes(Crypto.UTF8))));
  if(!result.getBoolean("complete"))throw new GeneralSecurityException("The server did not confirm the account move");v.activateTransfer(data,result.getJSONObject("account"));return Session.continueAccount(v,null,new String(password));
 }
 static boolean sourceComplete(Vault v)throws Exception{JSONObject out=v.transferOut();if(out==null)return false;if(out.optBoolean("confirmed"))return true;JSONObject result=request(v,"transferSourceStatus",new JSONObject().put("lookup",out.getString("lookup")));if(!out.getString("uid").equals(result.getString("uid")))throw new GeneralSecurityException("Transfer status mismatch");if(result.optBoolean("complete")){out.put("confirmed",true);v.transferOut(out);}return result.getBoolean("complete");}
 static java.io.File sourceHistory(Vault v,char[] pass)throws Exception{JSONObject out=v.transferOut();if(out==null||!MessageDigest.isEqual(passwordCheck(v,pass,out.getString("lookup")).getBytes(Crypto.UTF8),out.getString("passwordCheck").getBytes(Crypto.UTF8)))throw new GeneralSecurityException("Use the password that started this account move.");return v.transferFile(out.getString("lookup"));}
 static void eraseSource(Context context,Vault v)throws Exception{JSONObject out=v.transferOut();if(out==null||!out.optBoolean("confirmed"))throw new GeneralSecurityException("The receiving phone has not confirmed saving the account yet.");String lookup=out.getString("lookup"),proof=v.identity().getString("deviceSecret");SettingsActivity.removeLocalAccount(context,v);try{Session.request(Session.endpoint(),new JSONObject().put("operation","acknowledgeTransferSource").put("deviceSecret",proof).put("lookup",lookup),null,true);}catch(Exception ignored){/* One bounded private receipt may remain until the next move or account deletion. */}}
 static void cancel(Vault v)throws Exception{JSONObject out=v.transferOut();if(out==null)return;Repository.call(v,"cancelTransfer",new JSONObject().put("lookup",out.getString("lookup")));v.transferFile(out.getString("lookup")).delete();v.transferOut(null);}
 static void rollback(Vault v,char[] pass)throws Exception{JSONObject out=v.transferOut();if(out==null)throw new SecurityException("No account move is pending here.");String lookup=out.getString("lookup");if(out.optBoolean("rollbackPending")){try{Session.continueAccount(v,null,new String(pass));v.transferFile(lookup).delete();v.transferOut(null);return;}catch(Session.BackendException ignored){}}String nonce=request(v,"transferRollbackChallenge",new JSONObject().put("lookup",lookup)).getString("nonce");String context=String.join("\n","priperi-transfer-rollback-v1",lookup,out.getString("uid"),nonce,TransferCipher.hash(v.identity().getString("deviceSecret").getBytes(Crypto.UTF8)));out.put("rollbackPending",true);v.transferOut(out);JSONObject result=request(v,"rollbackTransfer",new JSONObject().put("lookup",lookup).put("nonce",nonce).put("password",new String(pass)).put("signature",v.crypto().sign(context.getBytes(Crypto.UTF8))));if(!result.optBoolean("rolledBack"))throw new GeneralSecurityException("The server did not confirm returning the account.");Session.continueAccount(v,null,new String(pass));v.transferFile(lookup).delete();v.transferOut(null);}
 static void discardReceiver(Context context,Vault v,char[] pass)throws Exception{JSONObject pending=v.transferIn();if(pending==null)throw new SecurityException("No unfinished receive is saved here.");if(!MessageDigest.isEqual(passwordCheck(v,pass,pending.getString("lookup")).getBytes(Crypto.UTF8),pending.getString("passwordCheck").getBytes(Crypto.UTF8)))throw new GeneralSecurityException("Use the password that started this move.");JSONObject state;try{state=Session.deviceStatus(v);}catch(Session.BackendException e){if(!"account-expired".equals(e.reason))throw e;state=new JSONObject().put("registered",false);}if(state.optBoolean("registered",true))throw new SecurityException("This phone still holds the account. Finish receiving it instead.");SettingsActivity.removeLocalAccount(context,v);}
 static void finishReceive(Vault v)throws Exception{if(v.transferIn()==null||v.account()==null||Session.uid()==null||!Session.uid().equals(v.transferIn().getString("uid")))throw new SecurityException("Finish signing in first.");JSONObject pending=v.transferIn();if(pending.optBoolean("includeHistory")&&!pending.optBoolean("historySaved"))throw new SecurityException("Choose the encrypted chats file to finish this move. The old phone keeps its copy until then.");String context=String.join("\n","priperi-transfer-finish-v1",pending.getString("lookup"),Session.uid(),TransferCipher.hash(v.identity().getString("deviceSecret").getBytes(Crypto.UTF8)),KeyDelegation.digest(Crypto.certificates(v.identity().optJSONArray("delegations"))));Repository.call(v,"finishTransfer",new JSONObject().put("lookup",pending.getString("lookup")).put("signature",v.crypto().sign(context.getBytes(Crypto.UTF8))));v.transferIn(null);}
 private AccountTransfer(){}
}
